from functools import wraps
import time

def medir_tiempo(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = func(*args, **kwargs)
        fin = time.perf_counter()
        print(f"{func.__name__} tomó {fin-inicio:.4f}s")
        return resultado
    return wrapper

@medir_tiempo
def operacion_lenta():
    return sum(range(1_000_000))

operacion_lenta()

from functools import wraps

def solo_enteros(func):
    """Valida que todos los argumentos sean enteros."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        for a in args:
            if not isinstance(a, int):
                raise TypeError(f"Se esperaba int, se recibió {type(a).__name__}")
        return func(*args, **kwargs)
    return wrapper

@solo_enteros
def sumar(a, b):
    return a + b

print(sumar(3, 4))    # 7
print(sumar(3, 4.5))  # TypeError

def reintentar(intentos: int = 3):
    """Decorador factory: reintenta la función si falla."""
    def decorador(func):
        from functools import wraps
        @wraps(func)
        def wrapper(*args, **kwargs):
            for i in range(intentos):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if i == intentos - 1:
                        raise
                    print(f"Intento {i+1} fallido: {e}")
        return wrapper
    return decorador

@reintentar(intentos=3)
def operacion_inestable():
    import random
    if random.random() < 0.7:
        raise ValueError("Fallo aleatorio")
    return "OK"

