    from functools import wraps
    def decorador(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            print(f"[{nivel}] Llamando {func.__name__}")
            resultado = func(*args, **kwargs)
            print(f"[{nivel}] {func.__name__} retornó {resultado}")
            return resultado
        return wrapper
    return decorador

@registrar("DEBUG")
def multiplicar(a, b):
    return a * b

multiplicar(3, 4)

from functools import wraps, lru_cache

@lru_cache(maxsize=128)
def fibonacci(n: int) -> int:
    """Fibonacci con memoización automática."""
    if n < 2:
        return n
    return fibonacci(n-1) + fibonacci(n-2)

print(fibonacci(40))  # 102334155
print(fibonacci.cache_info())

from functools import wraps

def solo_enteros(func):
    """Valida que todos los argumentos sean enteros."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        for a in args:
            if not isinstance(a, int):
                raise TypeError(f"Se esperaba int, se recibió {type(a).__name__}")
        return func(*args, **kwargs)
    return wrapper

@solo_enteros
def sumar(a, b):
    return a + b

print(sumar(3, 4))    # 7
print(sumar(3, 4.5))  # TypeError

from functools import wraps
import time

def medir_tiempo(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        inicio = time.perf_counter()
        resultado = func(*args, **kwargs)
        fin = time.perf_counter()
        print(f"{func.__name__} tomó {fin-inicio:.4f}s")
        return resultado
    return wrapper

@medir_tiempo
def operacion_lenta():
    return sum(range(1_000_000))

operacion_lenta()
